package server

// openapi_delegation.go — the delegation API (delegateapi.go, changeset.go;
// docs/protocol/delegation.md): endpoints() appends them.

func delegationEndpoints() []ep {
	const (
		tag     = "Delegation"
		person  = "the person, in their own session, app or device"
		orPage  = "the person, or their agent's own page under their login (it reads and pauses; it never grants)"
		orAgent = "the person, their agent's page, or their agent (a delegate call)"
		orOnlyA = "the person, or their agent (a delegate call)"
		agent   = "the person's workspace agent only (a delegate call)"
	)
	id := []oapi{pathParam("id", "the id")}
	return []ep{
		{"GET", "/delegate/state", tag, "A person's agent: its switches and what waits for them", orAgent,
			"{user, workspace (the workspace's switch), paused, adminChanges, canAdminChanges (the person is a workspace or org admin), pendingRequests, standingApprovals, openChangeSets, web, mcp, mcpReadOnly (the person's own settings for the web and MCP tools), net: {web: {policy, why?, only?}, mcp: {policy, why?}, search} (what the workspace policy lets them turn on, and why not), workspaceAt? (when the switch was last set), pausedAt?, and where this xbind ships an agent: access (the person was given one — an access entry names the component; an admin reads it as they manage it), agent? (the component whose page is their agent's conversation; only with access), held? (why it can't run now: older | locked | unavailable, with heldWhy for an admin), who? (a workspace admin: {everyone, entries, chosen})}.", nil, nil, "state"},
		{"POST", "/delegate/page/dismiss", tag, "Dismiss the notice that names the agent's page", "the person, or the shell they drive",
			"Once an admin has turned workspace agents on and this xbind has an agent to show, GET /alerts carries one alert of kind agent-page for each person — their own session and the shell they drive — naming /xbin/agent in words, for a shell that has no chip for the agent (its dismiss is this route). A POST ends it for that person, for good. Nothing else changes.",
			nil, nil, "{ok}"},
		{"PUT", "/delegate/state", tag, "Pause or resume your agent; let it propose admin changes, read the web, use MCP tools", orPage,
			"{paused?, adminChanges?, web?, mcp?, mcpReadOnly?} → the state. Pausing refuses the agent's every call at once (403 refusal paused) and cuts the ones running. The agent's page may send {paused: true} and nothing else (403): resuming, adminChanges, web, mcp and mcpReadOnly are the person's own session's; only a workspace or org admin can turn adminChanges on (403); web, mcp and mcpReadOnly can be turned on only while the workspace policy allows them (409 {refusal: policy}).", nil,
			jsonBody("switches", oapi{"paused": boolean(), "adminChanges": boolean(), "web": boolean(), "mcp": boolean(), "mcpReadOnly": boolean()}), "state"},
		{"GET", "/delegate/workspace", tag, "The workspace's switch and policy for workspace agents", "admin", "{enabled, by?, at?, agent?, who?: {everyone, entries, chosen}, web: {mode, allow, deny, search}, mcp: {mode} (the admin's own settings), policy: {web: {mode, allow, deny, hostAllow?, hostDeny?, search, byHost?}, mcp: {mode, byHost?}} (what is in force under the host's file), host: {active, lockAll, error?, web?, mcp?}, locks: {\"web.mode\": {locked, reason, ceiling?}, …}}. Off until an admin turns it on; who says who was given an agent.", nil, nil, "{enabled, by, at, agent, who, web, mcp, policy, host, locks}"},
		{"PUT", "/delegate/workspace", tag, "Turn workspace agents on or off; set their web and MCP policy", "admin",
			"{enabled?, who?, web?: {mode?: off | read, allow?, deny?, search?}, mcp?: {mode?: off | tiles}}, at least one. Off refuses every person's agent at once and cuts the calls running. who gives the agent to people, as access to its component: everyone (an entry in the workspace defaults), me (the admin's own entry; the defaults' goes), chosen (the defaults' entry goes, people's and orgs' own stay). web.mode full, web.search true and mcp.mode listed are reserved: 400 \"not available yet\". allow and deny are host patterns (example.com: it and the names under it; *.example.com: the names under it). Under the host's file (XBIN_WSAGENT_CONFIG) a mode past its ceiling is held to it; with its lockAll a web or mcp key is 409 {settings}. 409 where this xbind ships no agent or has no accounts.", nil,
			jsonBody("switch", oapi{"enabled": boolean(), "who": oapi{"type": "string", "enum": []string{"everyone", "me", "chosen"}}, "web": oapi{"type": "object"}, "mcp": oapi{"type": "object"}}), "{enabled, by, at, agent, who, web, mcp, policy, host, locks}"},
		{"POST", "/delegate/mcp/call", tag, "Call one tool of an MCP tile for the conversation", agent,
			"{server: \"<tile>\", tool, arguments} → {server, tool, isError, content: [{type, text?}], structured?}. xbind is the MCP client: it calls the tile's /api/<tile>/mcp as the person, through the tile's own rules (their level, its agent level — a tile at read takes only tools its server marks read-only), lists its tools (404 mcp-tool for one it doesn't), and needs the person's approval of this exact body (403 needs-approval: POST /delegate/requests, then X-XBin-Ticket) unless a standing approval of that tool covers it (\"always for this tool\": scope tool) or the tool is marked read-only (readOnlyHint) and the person's mcpReadOnly lets those through. 403 mcp-off, mcp-person (the policy, the person's setting), mcp-org (an org whose data the conversation holds keeps it from MCP servers outside it), tile, hidden. What the tool answers taints the conversation with the tile's orgs. On the tile's own endpoint the agent reads, unasked, exactly initialize, ping and tools/list (one JSON-RPC request a POST); anything else POSTed there is 403 mcp-call.", nil,
			jsonBody("the call", oapi{"server": str("the MCP tile's path"), "tool": str("the tool's name"), "arguments": oapi{"type": "object"}}, "server", "tool"), "the tool's answer"},
		{"POST", "/delegate/web/fetch", tag, "Read one web page for the conversation", agent,
			"{url} → {url, finalUrl, status, contentType, title?, text, bytes, truncated, redirects, readWeb}. xbind fetches it — GET only, no credentials, a fixed User-Agent, every address checked when its socket connects (public addresses only), at most 5 redirects each judged again, 2 MiB and 20 s at most, text out of the types it reads — under the workspace policy (403 refusal web-off), the person's setting (web-person) and the rules of the orgs whose data the conversation holds (web-org). The URL: http or https, at most 2 KiB, no user info, no numeric host form but a dotted quad, the allow and deny lists, never the workspace's own hosts (400 web-url, 403 web-host, web-address). A conversation that holds any org's data needs the person's approval of this exact body (403 needs-approval: POST /delegate/requests, then X-XBin-Ticket), unless every org it holds allows the web outright. 415 web-type, 429 rate-limited (12 a burst, one more every 5 s), 502/504 web-unreachable, web-redirect, web-timeout. Marks the session web: true. Every fetch is a row of the person's log.", nil,
			jsonBody("the page", oapi{"url": str("an absolute http or https URL")}, "url"), "page"},
		{"POST", "/delegate/sessions", tag, "Open an agent session: a conversation's scope and model", agent,
			"{scope: {orgs, tiles} | null, model: \"<upstream>/<model>\"} → {id, scope, model, tainted, created, used, connection: {counts}}. The handle is xbind's record of one conversation: what its person let it see (null: everything they can) and the model it is on. Every other delegate call carries its id as X-XBin-Agent-Session (403 {refusal: no-session} without; POST /delegate/sessions, GET /delegate/state, /whoami and the docs reads excepted). The gate asks the orgs' rules with the handle's model, refuses a tile outside its scope (403 {refusal: hidden}) and records the orgs whose tiles a call touched (tainted). At most 32 a person, gone after 24 h unused.", nil,
			jsonBody("session", oapi{"scope": oapi{"type": "object"}, "model": str("<upstream>/<model>")}, "model"), "session"},
		{"GET", "/delegate/sessions/{id}", tag, "One agent session", agent, "", id, nil, "session"},
		{"PATCH", "/delegate/sessions/{id}", tag, "Change an agent session's scope or model", agent,
			"{scope?, model?} → the session. The scope may always change. The model may change only to one every tainted org's rules allow: 409 {code: model_taint, orgs, reason} otherwise — start a new session.", id,
			jsonBody("change", oapi{"scope": oapi{"type": "object"}, "model": str("<upstream>/<model>")}), "session"},
		{"DELETE", "/delegate/sessions/{id}", tag, "End an agent session", agent, "204.", id, nil, "204"},
		{"GET", "/delegate/sessions/{id}/connection", tag, "What an agent session is connected to", agent,
			"{id, model, scope, orgs, tiles: [connected tiles], blocked: [{org, blocked, reason, rule}], counts, tainted, whatIf?}. Blocked, hidden and no-access tiles are counts and org-level reasons only — this answer enters a model's context. ?whatIf=<model> adds {model, connects, disconnects, counts, allowed, taintedOrgs}.", append(id, queryParam("whatIf", "another model", false)), nil, "connection"},
		{"GET", "/delegate/start-defaults", tag, "What a tile agent started there would open with", agent,
			"?tile= → {tile, harness, harnesses: [{id, name, mode, asks, net, api, needsTicket}], why?}. Per harness the tile's orgs' rules allow: the mode, network and tile-API access a start that names none opens with — the person's preference for agent-started sessions, or the harness's asking mode — and whether the person approves each start (needsTicket). harness is the default: the first that starts unasked, else the first allowed. The person needs terminal access to the tile (403).", []oapi{queryParam("tile", "tile path", true)}, nil, "start defaults"},
		{"POST", "/delegate/sessions/{id}/allows", tag, "Does the session's model satisfy these orgs' rules?", agent,
			"{orgs: [id, …]} → {id, model, allowed, reasons: {org: why}}. Each org must be one the person can see (\"workspace\", an org of theirs, one a tile they read is under): 403 otherwise.", id, jsonBody("orgs", oapi{"orgs": oapi{"type": "array", "items": str("org id")}}, "orgs"), "{allowed, reasons}"},
		{"POST", "/delegate/sessions/{id}/taint", tag, "Add orgs to an agent session's taint", agent,
			"{orgs?: [id, …], web?: true}, at least one → the session. For data the conversation took in where xbind didn't see it (the agent's own notebook), and what a conversation holds that a handle it renews must carry (web: it has read the web). Add-only: nothing removes an org or clears web. Orgs the person can see (403), and whose rules the session's model satisfies (409 {code: model_taint, orgs, reason}).", id, jsonBody("orgs", oapi{"orgs": oapi{"type": "array", "items": str("org id")}, "web": boolean()}), "session"},
		{"GET", "/delegate/map", tag, "The workspace as the person sees it, compact", "a person, or their agent (with an agent session)",
			"{user, tiles: [{tile, title, kind, orgs, state, agent, tileAgents}], screens: [{id, name, org?, tiles}], orgs, leftOut: {hiddenByYou, blocked}} — within the session's scope and the orgs' rules; what is left out is counted, not named.", nil, nil, "map"},
		{"GET", "/docs/search", tag, "Search the docs", "signed in (a person, their agent, a tile)",
			"?q= (≤ 200 bytes, 8 words) &limit= (≤ 20, default 8) → {q, results: [{path, title, section, heading, score, snippet}], total}. Ranked: a word in the page's title 10, in the section's heading 5, in its body 1 each (≤ 5); every word must match.", []oapi{queryParam("q", "words", true), queryParam("limit", "≤ 20", false)}, nil, "{results}"},
		{"GET", "/docs/page", tag, "One docs page, or one section of it", "signed in (a person, their agent, a tile)",
			"?path= (as search answers) &section= (a heading's slug) → {path, title, section?, markdown, truncated?, sections: [{section, heading}]}; at most 64 KiB. 404 for a path or section that isn't there.", []oapi{queryParam("path", "docs page", true), queryParam("section", "heading slug", false)}, nil, "page"},
		{"GET", "/agent-levels", tag, "What people's agents may do in each tile, as approved", "a person who manages tiles, in their own session",
			"{tiles: [{tile, level, requested?, stated?, builtin?, by?, at?}]} for the tiles the caller may manage that have a level on record or a raise waiting. level is the one in force (off | read | full): the manifest's \"agent\", never above what was last approved for the tile. requested is what the manifest asks for now when that is more — it waits for PUT /agent-levels. builtin: one of the workspace's consoles, held at this xbind's level. Never a tile's credential, a person's workspace agent or a view-as session (403).", nil, nil, "{tiles}"},
		{"PUT", "/agent-levels", tag, "Approve the raise a tile's manifest asks for", "the tile's owner, an admin of the owning org, or a workspace admin — in their own session",
			"{tile, level} → the tile's row. A tile's manifest lowers its level at once; a manifest that states more than the level on record, or drops the key after stating less, changes nothing until this call. level is the level being approved and must be what the manifest asks for now (409 otherwise). 403 for anyone who doesn't manage the tile, and for every credential that isn't a person's own session; 409 for a console.", nil,
			jsonBody("the approval", oapi{"tile": str("tile path"), "level": str("read | full — what the manifest asks for")}, "tile", "level"), "{tile, level, stated?, by, at}"},
		{"GET", "/delegate/audit", tag, "What my agent did", person + "; an admin with ?user=",
			"{user, calls: [{ts, user, agent, method, path, tile?, class, effect?, dryRun?, status, refused?, ticket?, under?}]}, newest first: every side effect, tile call, refusal, read of code, logs or admin state, approval decision and applied change-set operation. Never a body, a query or a header. 13 months are kept. Never readable by the agent, its page, a tile or a view-as session.",
			[]oapi{queryParam("before", "rows older than this RFC 3339 time", false), queryParam("limit", "at most this many (default 200, max 1000)", false), queryParam("user", "admin: another person's log", false)}, nil, "{user, calls, skipped?}"},
		{"POST", "/delegate/requests", tag, "Ask the person to approve one side effect", agent,
			"{method, path, body? | bodyBase64?, contentType?, summary?} → the request, pending. path is the call exactly as it will be sent (under /api/, with its query; ≤ 2048 bytes, no _method); body what it will carry (≤ 256 KiB); contentType the Content-Type it will carry (application/json when there is a body and none is said) — all of it is what the ticket binds. Only a call that needs approval: a non-GET call to a tile's API, POST /term/sessions, POST /templates/new (400 otherwise). xbind judges it as the gate will (403 when the tile or its org refuses it anyway), stores it with its own preview — for a session start the tile, harness, mode, whether that mode asks before acting, network and API access — and tells the person (a `delegate` event, a push). 409 past 20 pending.", nil,
			jsonBody("the call", oapi{"method": str("POST | PUT | PATCH | DELETE"), "path": str("/api/<tile>/… or /api/xbin/term/sessions"), "body": str("the body, as text"), "bodyBase64": str("…or as standard base64"), "contentType": str("the call's Content-Type (default application/json with a body)"), "summary": str("the agent's own words, shown as the agent's (≤ 500 chars)")}, "method", "path"), "request"},
		{"GET", "/delegate/requests", tag, "The requests waiting for me", orPage,
			"{requests: [request]}, oldest first: {id, user, agent, kind (call | session | template), method, target, tile?, contentType?, body?, bodyShown, bodySize, bodySha256, summary?, preview (for a tile call with standing: {call, tile} — xbind's sentence for each standing scope), state (pending | approved | denied | used | expired | withdrawn), grant?, created, decided?, expires, decidedVia?}. ?all=1 adds the ones decided in the last day.", []oapi{queryParam("all", "1: decided ones too", false)}, nil, "{requests}"},
		{"GET", "/delegate/requests/{id}", tag, "One request", orAgent, "The agent polls this: state approved means its id is a ticket now.", id, nil, "request"},
		{"POST", "/delegate/requests/{id}/approve", tag, "Approve a request", person + " — never the agent's page, which renders what the agent wrote",
			"{grant?: once | hour | always, scope?: call | tile, unseen?: true} → {request, approval?}. A request whose body can't be shown as text (bodyBinary: not UTF-8, or with control characters; preview.body {binary, size, sha256}) is approved only with unseen: true (409 {unseen, bodySize, bodySha256} without); the request then records approvedUnseen. once (the default): the request becomes a one-shot ticket for exactly that method, path, query, body and content type, good for 15 minutes — the agent sends its id as X-XBin-Ticket. hour / always (a tile API call only): also a standing approval — of this call, its method and path with any body (scope call, the default), or of every write to the tile's API (scope tile: the wider, explicit choice). 409 when it is no longer pending. While the person's agent is stopped (workspace agents off, paused, held, not given to them) this is 409 {error, refusal: workspace-off | paused | held | no-agent}: nothing is allowed then.", id,
			jsonBody("grant", oapi{"grant": str("once | hour | always"), "scope": str("call (default) | tile — what a standing approval covers"), "unseen": boolean()}), "{request, approval?}"},
		{"POST", "/delegate/requests/{id}/deny", tag, "Deny a request", person, "→ {request}. 409 when it is no longer pending.", id, nil, "{request}"},
		{"DELETE", "/delegate/requests/{id}", tag, "Withdraw a request", orOnlyA, "A pending or approved request the agent no longer wants. → the request.", id, nil, "request"},
		{"GET", "/delegate/approvals", tag, "The standing approvals", orAgent, "{approvals: [{id, user, tile, scope (call | tile), method?, path?, until? (absent: until revoked), created, via?, request?}]}: what the agent may do without a ticket — one call (scope call: method on path of the tile's API, any body and query) or every write to a tile's API (scope tile). An approval goes when its tile is deleted or the person can no longer read it.", nil, nil, "{approvals}"},
		{"POST", "/delegate/approvals", tag, "Let the agent write to a tile's API without asking", person,
			"{tile, grant: hour | always, scope: call, method, path} or {tile, grant, scope: tile} → the approval. scope is required: call approves that method on that path of the tile's API (/api/<tile>/…, no query); tile every write to it. The same approval again replaces the old one. A tile the person can read (404 otherwise). Never covers a session start or a tile create. While the person's agent is stopped (workspace agents off, paused, held, not given to them) this is 409 {error, refusal: workspace-off | paused | held | no-agent}: nothing is allowed then.", nil, jsonBody("approval", oapi{"tile": str("tile path"), "grant": str("hour | always"), "scope": str("call | tile"), "method": str("scope call: POST | PUT | PATCH | DELETE"), "path": str("scope call: /api/<tile>/…")}, "tile", "grant", "scope"), "approval"},
		{"DELETE", "/delegate/approvals/{id}", tag, "Revoke a standing approval", person, "204. The agent's next write needs a ticket again; one running under it is cut.", id, nil, "204"},
		{"POST", "/delegate/changesets", tag, "Propose admin changes", agent,
			"{title, items: [{kind, args, why?}]} → the change set, proposed; nothing is applied. Only for an admin who opted in (adminChanges; 403). kind: grant.add | grant.revoke {from, target, role}; binding.set {component, slot, provider | providers, host?, zone?, listen?, add?}; binding.remove {component, slot, provider?, host?, zone?, listen?}; org.share {org, tile, level}; limits.set {tile, kind, value} — no other (400). Also 400: an operation on a workspace agent; a grant of xbin, xbin:*, cap:*, gpu:*, code or net:*; a binding of an @ pseudo-slot, of the workspace default or to the host's network; a share of a tile that holds such a grant. Each item comes back with xbind's own line, before, after, effects, warnings and blocked (the handler's refusal, when it would refuse). At most 20 items; 409 past 10 open sets.", nil,
			jsonBody("change set", oapi{"title": str("what it is for"), "items": oapi{"type": "array", "items": oapi{"type": "object"}}}, "items"), "change set"},
		{"GET", "/delegate/changesets", tag, "My agent's change sets", orAgent, "{changesets: [{id, user, agent?, title, undoOf?, state (proposed | applying | applied | partial | rejected | expired | withdrawn), created, decided?, expires, items: [{n, kind, args, why?, line, before?, after?, effects?, warnings?, blocked?, inverse?, result?, error?}]}]}. A proposal expires after 7 days.", nil, nil, "{changesets}"},
		{"GET", "/delegate/changesets/{id}", tag, "One change set", orAgent, "", id, nil, "change set"},
		{"DELETE", "/delegate/changesets/{id}", tag, "Withdraw a change set", orOnlyA, "A proposal nobody decided yet. → the change set.", id, nil, "change set"},
		{"POST", "/delegate/changesets/{id}/approve", tag, "Approve a change set and apply it", person + " — the person whose agent proposed it",
			"{items: [n, …], password?} → the change set with each item's result: applied | failed | stale | skipped | rejected | blocked. Step-up, as for adding a device: the sign-in is under 10 minutes old or the body carries the password (403 {error, stepUp: password | signin}). xbind applies the chosen items — items is required and not empty: no body, null and [] apply nothing (400, the set stays proposed) — in order as the person, through the admin handlers everyone uses. An item whose state — or xbind's line, effects or warnings for it — changed since it was proposed is stale and not applied; after the first failure the rest are skipped; what was applied stays (…/undo proposes the set that undoes it). While the person's agent is stopped (workspace agents off, paused, held, not given to them) this is 409 {error, refusal: workspace-off | paused | held | no-agent}: nothing is applied.", id,
			jsonBody("approval", oapi{"items": oapi{"type": "array", "items": integer()}, "password": str("step-up: the account password")}, "items"), "change set"},
		{"POST", "/delegate/changesets/{id}/reject", tag, "Reject a change set", person, "→ the change set. 409 when it is no longer proposed.", id, nil, "change set"},
		{"POST", "/delegate/changesets/{id}/undo", tag, "Propose the set that undoes an applied one", person, "→ a new change set of the person's own (undoOf), holding the inverse of each applied item that has one, newest first — approved like any other. 409 when nothing of it can be undone by xbind.", id, nil, "change set"},
	}
}
